function cleanReplyText(text) {
  return String(text || '')
    // Tags internas: nunca devem aparecer para o cliente
    .replace(/\[(?:AÃ‡ÃƒO|ACAO)\s*:\s*[^\]]+\]/gi, '')
    .replace(/\[HUMANO_SOLICITADO\]/gi, '')
    .replace(/\[PRONTO_PARA_AGENDAR\]/gi, '')
    .replace(/\[RECLAMACAO\]/gi, '')

    // Desescapa Markdown que alguns modelos devolvem como "\*\*" / "\-"
    .replace(/\\([*_`~>#\-\[\]()])/g, '$1')

    // Remove Markdown e mantÃ©m texto legÃ­vel no Telegram sem parse_mode
    .replace(/\*\*([^*]+)\*\*/g, '$1')
    .replace(/__([^_]+)__/g, '$1')
    .replace(/`([^`]+)`/g, '$1')
    .replace(/^\s*#{1,6}\s*/gm, '')
    .replace(/^\s*[-*]\s+/gm, 'â€¢ ')

    // Limpeza de espaÃ§os
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
