function classify(context = {}) {
  const settings = settingsFor(context);
  let service = 'geral';
  let stage = 'Qualificacao';
  let handoff = false;

  const botFrustrationOnly = isBotFrustrationText() && !isRealServiceComplaintText();

  for (const rule of asArray(settings.classification_rules || settings.intent_rules)) {
    if (!matchKeywords(rule.keywords || rule.triggers)) continue;

    const matched = {
      service: rule.service || rule.intent || service,
      stage: rule.stage || stage,
      handoff: Boolean(rule.handoff),
    };

    // "IA burra", "nÃ£o foi isso", etc. = corrigir a resposta, nÃ£o abrir reclamaÃ§Ã£o formal.
    if (botFrustrationOnly) {
      matched.stage = 'Qualificacao';
      matched.handoff = false;
    }

    return matched;
  }

  if (isRealServiceComplaintText()) {
    stage = 'Atendimento humano';
    service = 'reclamacao';
    handoff = true;
  } else if (botFrustrationOnly) {
    stage = 'Qualificacao';
    handoff = false;
  } else if (hasAny(['orcamento complexo', 'proposta comercial', 'contrato'])) {
    stage = 'Orcamento solicitado';
    handoff = true;
  } else if (hasAny(['quanto custa', 'preco', 'precos', 'valor', 'valores', 'tabela'])) {
    // Perguntar preÃ§o Ã© uma dÃºvida normal; a IA deve responder usando catÃ¡logo/prompt.
    stage = 'Tabela de precos';
    handoff = false;
  } else if (hasAny(['humano', 'atendente', 'especialista', 'falar com alguem', 'falar com alguÃ©m', 'reuniao', 'ligar', 'whatsapp'])) {
    stage = 'Atendimento humano';
    handoff = true;
  } else if (hasAny(['urgente', 'fora do ar', 'parado', 'caiu', 'nao funciona', 'nÃ£o funciona'])) {
    stage = 'Suporte tecnico';
    handoff = true;
  } else if (hasAny(['agendar', 'agenda', 'consulta', 'horario', 'horÃ¡rio', 'visita', 'marcar'])) {
    stage = 'Agendamento';
  } else if (hasAny(['comprar', 'fechar', 'venda', 'pedido'])) {
    stage = 'Interesse comercial';
  }

  if (hasAny(['sistema', 'software', 'app', 'aplicativo', 'site', 'landing page', 'automacao', 'automaÃ§Ã£o', 'integracao', 'integraÃ§Ã£o', 'api', 'crm', 'dashboard'])) service = 'software_automacao';
  else if (hasAny(['suporte', 'erro', 'computador', 'notebook', 'internet', 'rede', 'servidor', 'email', 'impressora', 'ti', 'manutencao', 'manutenÃ§Ã£o'])) service = 'suporte_ti';
  else if (hasAny(['trafego', 'trÃ¡fego', 'anuncio', 'anÃºncio', 'google ads', 'meta ads', 'facebook ads', 'campanha', 'leads'])) service = 'trafego_pago';
  else if (hasAny(['social media', 'instagram', 'conteudo', 'conteÃºdo', 'post', 'reels', 'criativo'])) service = 'social_media';
  else if (hasAny(['consulta', 'clinica', 'clÃ­nica', 'paciente', 'agendamento', 'bronze', 'bronzeamento'])) service = 'agendamento_atendimento';

  return { service, stage, handoff };
}

function normalizeConfiguredFallbackMessage(value) {
  const text = String(value || '').trim();

  const legacy = normalizeText(
    'Desculpe, nao consegui entender. Pode reformular sua pergunta?'
  );

  if (normalizeText(text) === legacy) {
    return 'Desculpe, nÃ£o consegui entender. Pode reformular sua pergunta?';
